CREATE TABLE user (
    user_id INT PRIMARY KEY AUTO_INCREMENT,
    username VARCHAR(50) UNIQUE,
    password VARCHAR(100),
    role varchar(25),
    age INT,
    region varchar(255));
CREATE TABLE admin( admin_id INT PRIMARY KEY AUTO_INCREMENT,
                    adminname VARCHAR(50) UNIQUE,
                    password VARCHAR(100),
                    role varchar(25));
CREATE TABLE recommendation_history ( id INT PRIMARY KEY AUTO_INCREMENT,
                                      user_id INT,
                                      car_id INT,
                                      score FLOAT,
                                      timestamp DATETIME,
                                      name varchar(255)
);
CREATE TABLE default_recommendations (
                                         id INT PRIMARY KEY AUTO_INCREMENT,
                                         car_id INT,
                                         brand_name VARCHAR(255),
                                         full_name VARCHAR(255),
                                         price VARCHAR(255)

);

DELIMITER //
CREATE PROCEDURE InsertRecommendationData()
BEGIN
    DECLARE user_counter INT DEFAULT 1;
    DECLARE record_counter INT;
    DECLARE random_car_id INT;
    DECLARE random_car_name VARCHAR(255);

    -- 循环处理每个 user_id
    WHILE user_counter <= 330 DO
            -- 有 50% 的概率跳过当前 user_id
            IF RAND() > 0.5 THEN
                -- 随机决定每个 user_id 的记录数（0 到 20 条）
                SET record_counter = FLOOR(RAND() * 21);

                -- 插入记录
                WHILE record_counter > 0 DO
                        -- 从 cars 表中随机选取一条记录
                        SELECT car_id, name INTO random_car_id, random_car_name
                        FROM car_info
                        JOIN car_brand dr on car_info.brand_id = dr.brand_id
                        ORDER BY RAND()
                        LIMIT 1;

                        VALUES (
                                   user_counter,
                                   random_car_id,
                                   RAND() * 10,  -- 随机 score 范围 1 到 10
                                   DATE_ADD(NOW(), INTERVAL -FLOOR(RAND() * 365) DAY),  -- 随机 timestamp 范围过去一年
                                   random_car_name
                               );
                        SET record_counter = record_counter - 1;
                    END WHILE;
            END IF;

            SET user_counter = user_counter + 1;
        END WHILE;
END //
DELIMITER ;
-- 调用存储过程
CALL InsertRecommendationData();

-- 清空表的两种方式
-- 使用 DELETE 语句
-- DELETE FROM recommendation_history;

-- 使用 TRUNCATE 语句
TRUNCATE TABLE recommendation_history;

-- 删除存储过程
DROP PROCEDURE IF EXISTS InsertRecommendationData;
